def solve():
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        n = int(input_data)
    except ValueError:
        return

    count = 0
    def backtrack(current):
        nonlocal count
        if len(current) == 3:
            count += 1
            return
        for digit in range(1, n + 1):
            backtrack(current + str(digit))

    backtrack("")
    print(count)

